bloquearClasAdmin = function(){
  $('.clasAdminCombo').each(function(){
    if( $(this).is('select')){
      $(this).prop('disabled', true);
      $(this).selectpicker('refresh');
    }
  });
}

desbloquearClasAdmin = function(){
  $('.clasAdmin-bloqueado').remove();
  $('.clasAdminCombo').each(function(){
    if( $(this).is('select')){
      $(this).prop('disabled', false);
      $(this).selectpicker('refresh');
    }
  });
}
validaClasADmin = function(){
  seleccionados = true;
  if( $("#comboue").length ){
    if( $("#comboue").val() == '' ){
      $("#comboue").parent().parent().addClass('faltaSelect');
      seleccionados = false;
    }
  }
  if( $("#comboprg").length ){
    if( $("#comboprg").val() == '' ){
      $("#comboprg").parent().parent().addClass('faltaSelect');
      seleccionados = false;
    }
  }
  if( $("#combosp").length ){
    if( $("#combosp").val() == '' ){
      $("#combosp").parent().parent().addClass('faltaSelect');
      seleccionados = false;
    }
  }
  if( $("#combopy").length ){
    if( $("#combopy").val() == '' ){
      $("#combopy").parent().parent().addClass('faltaSelect');
      seleccionados = false;
    }
  }
  if( $("#combooa").length ){
    if( $("#combooa").val() == '' ){
      $("#combooa").parent().parent().addClass('faltaSelect');
      seleccionados = false;
    }
  }
  if(!seleccionados){
    $("#clasAdminSeccionCombos").show();
    var warningClasAdmin = setInterval(function() { $('.faltaSelect').toggleClass('danger'); }, 200);
    setTimeout(function() { clearInterval(warningClasAdmin); }, 1500);
    setTimeout(function() { clearInterval(warningClasAdmin); $('.faltaSelect').removeClass('danger');}, 2500);
  }else
    $("#clasAdminSeccionCombos").hide();
  return seleccionados;
}
  
limpiaClasAdmin = function(){ comunica("srv/ClasificacionAdministrativaB.php",{metodoClasAdmin:"limpiaClasAdmin"}); desbloquearClasAdmin(); }