// JavaScript Document
(function($){
  $.widget("wr.menusinpres",{
    sistemaActivo:null,
    menuActivo:null,
    opcionActivo:null,
    nivelBreadcrumbs:0,
    funcionesBreadcrumbs:[],
    menu:$('<ul/>').addClass('menu'),
    breadcrumbs :$('<ul/>').addClass('breadcrumbs'),
    options: {sistema:'poas',sis_id:'A',menu:[{ texto:'Menu1', id:'1', opciones:[{ id:'1', controlador:'NombreControlador',texto:'Opcion1' }] }] },
    _create: function(){  
      var self = this, o = self.options, $el = self.element;
      self.sistemaActivo = o.sis_id;
      $el.addClass('sombra-2');
      self._creaMenu();
      
      
    },
    _setOption: function (key, value) {
      var o = this.options;
      switch(key){
        case 'menu' :
          this.element.hide("slide");
          o.menu = value;
          this._creaMenu();
          this.element.show("slide");
        break;
        case 'sistema':
          $('.modulos .modulo.active').removeClass('active');
          $('#sis17_' + value.toUpperCase()).addClass('active');
          o.sistema = value;
        break;
        case 'sis_id': 
          this.sistemaActivo = value;
          o.sis_id = value;
        break;  
      }
      this._super("_setOption", key, value);
    },
    _creaMenu:function(){
      var self = this, o = self.options, $el = self.element;
      self.menu = $('<ul/>').addClass('menu');
      for (var x in o.menu){
        o.menu[x].elemento = $('<li/>').text( o.menu[x].texto ).prop('id', o.sis_id + o.menu[x].id ).prop('men_id', o.menu[x].id );
        // o.menu[x].elemento.click(function(){ self._colocarOpciones( $(this).prop('men_id') ); });
        var $opciones = $('<ul/>').addClass('subs');
        for (var y in o.menu[x].opciones){
          $opc = $('<li/>')
            .attr('id','li'+self.sistemaActivo + o.menu[x].id + o.menu[x].opciones[y].id)
            .prop('men_id',o.menu[x].id)
            .prop('opc_id',o.menu[x].opciones[y].id)
            .html('<h3 class="panel-title"><span> <i class="fa fa-user-plus"></i> </span><stronge>'+ o.menu[x].opciones[y].texto  +'</stronge></h3>')
            .click(function(){ 
              self._colocarOpciones( $(this).prop('men_id') );
              $('#contenedor').empty();
              self._clickOpcion( $(this).prop('opc_id'),$(this).prop('men_id') );
            });
          $opciones.append($opc);
        }
        o.menu[x].elemento.append($opciones);
        self.menu.append( o.menu[x].elemento );
      }
      self.breadcrumbs.empty().addClass('hide');
      $men =  $('<div class="container"/>');
      $men.html( self.menu ).append( self.breadcrumbs );
      self.element.html( $men );
      // self.element.html( self.menu ).append( self.breadcrumbs );
      ActivaAtajosMenu();
    },
    _colocarOpciones:function(m){
      ActivaAtajosMenu();
      var self = this;
      self.nivelBreadcrumbs = 1;
      self.menuActivo = m;
      self.opcionActivo = null;
      self.menu.addClass('hide'); self.breadcrumbs.removeClass('hide');
      self.breadcrumbs.html( $('<li />').attr('title','Menu Principal').addClass('home').tooltip().html( $('<a id="homeMenu" href = "#" />').html( $('<span />').html('<span class="glyphicon glyphicon-arrow-left" />') ) ).click(function(){ self._home(); }) )
      .append( $('<li />').addClass('current').html( $('<a href = "#" />').html( $('<span />').html(self.options.menu[m].texto) ) ) );
      self._zindex();
      $('#contenedor').empty();
      
      var $opciones = $('<ul/>').addClass('subs');
      for (var y in self.options.menu[m].opciones){
        $opc = $('<li/>')
          .attr('id','li'+self.sistemaActivo + self.options.menu[m].id + self.options.menu[m].opciones[y].id)
          .prop('men_id',self.options.menu[m].id)
          .prop('opc_id',self.options.menu[m].opciones[y].id)
          .html('<h3 class="panel-title"><span> <i class="fa fa-user-plus"></i> </span><stronge>'+ self.options.menu[m].opciones[y].texto  +'</stronge></h3>')
          .click(function(){
            self._clickOpcion( $(this).prop('opc_id'));
          });
        $opciones.append($opc);
      }
      $('#contenedor').append($opciones);
      
      $('#toolsPantalla.tools').empty();
      limpiaClasAdmin();
      //$("#clasAdminSeccion").clasadmin('limpiaClasAdmin');
    },
    _clickOpcion:function( opcion,menu){

      // Marcos: Para que funcione en Chrome, que no admite inicialización de valores default en la declaración de la función
      menu = typeof menu !== 'undefined' ? menu : 0;

      var self = this;
      if( self.nivelBreadcrumbs == 2 ){
        self.breadcrumbs.find('.current').remove();
      }
      if(menu == 0 )
        menu = self.menuActivo;
      else
        self.menuActivo = menu;
      self.nivelBreadcrumbs = 2;
      self.opcionActivo = opcion;
      self.breadcrumbs.find('.current').removeClass('current').click(function (){ self._colocarOpciones( self.menuActivo  ); });
      self.breadcrumbs.append( $('<li />').attr('id', self.sistemaActivo + self.menuActivo + self.options.menu[menu].opciones[opcion].id ).attr('opc_id', self.options.menu[menu].opciones[opcion].id ).addClass('current').html( $('<a href = "#" />').html( $('<span />').html( self.options.menu[menu].opciones[opcion].texto ) ) ) );
      self._zindex();
      
            if(self.options.sistema =="scp" && self.options.menu[menu].opciones[opcion].folder !="" )
                comunica(self.options.sistema +'/'+ self.options.menu[menu].opciones[opcion].folder +'/' + self.options.menu[menu].opciones[opcion].controlador + '.php');
            else
                comunica(self.options.sistema +'/'+ self.options.menu[menu].opciones[opcion].controlador + '.php');
      
    },
    _home:function(){
      var self = this;
      self.menuActivo = null;
      self.opcionActivo = null;
      self.nivelBreadcrumbs = 0;
      self.breadcrumbs.addClass('hide');
      self.menu.removeClass('hide');
      limpiaClasAdmin();
      $('#toolsPantalla.tools,#contenedor').empty();
    },
    _zindex:function(){
      var x = this.breadcrumbs.find('li').length;
      this.breadcrumbs.find('li').each(function(){
        $(this).css('z-index',x);
        x--;
      });
    },
    mousetrapMenu:function(m,o){
      var self = this;
      self.menuActivo = "_" + m;
      self.opcionActivo = "_" + o;
      self.menu.addClass('hide');
      self.breadcrumbs.removeClass('hide');
      self.breadcrumbs.html( $('<li />').attr('title','Menu Principal').addClass('home').tooltip().html( $('<a id="homeMenu" href = "#" />').html( $('<span />').html('<span class="glyphicon glyphicon-arrow-left" />') ) ).click(function(){ self._home(); }) )
      .append( $('<li />').html( $('<a href = "#" />').html( $('<span />').html(self.options.menu[self.menuActivo].texto) ) ).click(function (){ self._colocarOpciones( self.menuActivo  ); }) )
      .append( $('<li />').attr('id', self.sistemaActivo + self.menuActivo + self.options.menu[self.menuActivo].opciones[self.opcionActivo].id ).attr('opc_id', self.options.menu[self.menuActivo].opciones[self.opcionActivo].id ).addClass('current').html( $('<a href = "#" />').html( $('<span />').html( self.options.menu[self.menuActivo].opciones[self.opcionActivo].texto ) ) ) );
      self._zindex();
      //$("#clasAdminSeccion").clasadmin('limpiaClasAdmin');
      comunica("srv/Controlador.php",{metodo:"tienePantallaAyuda", idPantalla: self.sistemaActivo + self.menuActivo.replace("_","") + self.options.menu[self.menuActivo].opciones[self.opcionActivo].id.replace("_","") });   /* ayuda */
      comunica(this.options.sistema +'/'+ this.options.menu[self.menuActivo].opciones[self.opcionActivo].controlador + '.php');
    },
    opcionActiva:function(){
      var menid = (this.menuActivo == null) ?null :this.menuActivo.replace('_',''), opcid = (this.opcionActivo == null) ?null :this.opcionActivo.replace('_','');
      return opc = { sis_id : this.sistemaActivo, men_id : menid, opc_id : opcid, claveOpcion : this.sistemaActivo + '_' + menid + '_' + opcid }
    },
    clickHome:function(){ this._home(); },
    clickMenu:function(){
      m = this.menuActivo;
      this._colocarOpciones(m);
    },
    clickOpcion:function(){
      var self = this,
      menu = self.menuActivo,
      o = self.opcionActivo,
      selector = '#' + self.sistemaActivo + self.menuActivo + self.options.menu[menu].opciones[o].id;
      while($(selector).next().length){
        self.nivelBreadcrumbs--; 
        $(selector).next().remove();
      }
      $('#' + self.sistemaActivo + self.menuActivo + self.options.menu[menu].opciones[o].id).remove();
      this._clickOpcion(o);
    },
    agregaBreadcrumbs:function(datos){
      var self = this;
      if( self.nivelBreadcrumbs > 1 ){
        if( self.nivelBreadcrumbs == 2 )
          self.breadcrumbs.find('.current').removeClass('current').click(function (){
            while($(this).next().length){
              self.nivelBreadcrumbs--; 
              $(this).next().remove();
            }
            $(this).addClass('current').unbind('click'); 
            comunica(self.options.sistema +'/'+ self.options.menu[self.menuActivo].opciones[self.opcionActivo].controlador + '.php');
          });
        else
          self.breadcrumbs.find('.current').removeClass('current').click( self.funcionesBreadcrumbs[self.nivelBreadcrumbs] );
        self.nivelBreadcrumbs++;
        self.funcionesBreadcrumbs[ self.nivelBreadcrumbs ] = datos.funcion;
        self.breadcrumbs.append( $('<li />').attr('id','nivelBreadcrumbs'+self.nivelBreadcrumbs).addClass('current breadcrumbsHijo' + self.sistemaActivo + self.menuActivo + self.opcionActivo).html( $('<a href = "#" />').html( $('<span />').html( datos.texto ) ) ) );
        self._zindex();
      }
    },
    quitaBreadcrumbs:function(){
      this.nivelBreadcrumbs--;
      // $('nivelBreadcrumbs'+self.nivelBreadcrumbs).click().remove();
      var n = parseInt($(".breadcrumbs > li.current").css("z-index"));
      var n = n+1;
      $(".breadcrumbs > li").each(function(){
        if($(this).css("z-index")==n){
        
        $(".breadcrumbs > li.current").remove();
        $(this).addClass("current");
        }
      });

    },
    destroy: function(){
      this._destroy();
      // we can probably remove the unbind calls in 2.0
      // all event bindings should go through this._on()
      this.element
        .unbind( this.eventNamespace )
        // 1.9 BC for #7810
        // TODO remove dual storage
        .removeData( this.widgetName )
        .removeData( this.widgetFullName )
        // support: jquery <1.6.3
        // http://bugs.jquery.com/ticket/9413
        .removeData( $.camelCase( this.widgetFullName ) );
      this.widget()
        .unbind( this.eventNamespace )
        .removeAttr( "aria-disabled" )
        .removeClass(
          this.widgetFullName + "-disabled " +
          "ui-state-disabled" );
      // clean up events and states
      this.bindings.unbind( this.eventNamespace );
      this.hoverable.removeClass( "ui-state-hover" );
      this.focusable.removeClass( "ui-state-focus" );
    },
    _destroy: $.noop,
  });
  
})(jQuery);

