soloNumeros = function (event) {
  // console.log(event.keyCode);
  var permitido = [
    8,//borrar
    9,//tab
  ];
  if(event.shiftKey)
    event.preventDefault();
  else if( (permitido.indexOf(event.keyCode) == -1 ) && (( event.keyCode < 96 && (event.keyCode < 48 || event.keyCode > 57) ) || event.keyCode > 105) )
    event.preventDefault();
}

alerta = function (){
    var tituloAlerta = '';
    var mensaje = '';
    switch(arguments.length){
      case 1:
        switch( typeof arguments[0]){
          case 'string': mensaje = arguments[0]; break;
          case 'object':
            tituloAlerta = $('<div />').addClass('modal-header')
              .html( 
                $('<button />').attr('type','button')
                        .addClass('close')
                        .attr('data-dismiss','modal')
                        .attr('aria-hidden','true') 
              ).append(
                $('<h4 />').addClass('modal-title')
                      .attr('id','tituloAlerta')
                      .html( 'tituloAlerta' )
              );
            var pie = $('<div />').addClass('modal-footer')
                .html( 
                  $('<button />').addClass('btn btn-default')
                    .attr('type','button')
                    .attr('data-dismiss','modal')
                    .html('Cerrar') 
                )
          break;
          default:
            console.error('Tipo de dato '+ typeof arguments[0] +' no esperado en funcion alerta');
            return false;
          break;
        }
      break;
      default:
        var tipo = '';
        if( typeof arguments[0] !== 'string' || typeof arguments[1] !== 'string' ){
          console.error('tipo de dato no esperado en funcion alerta');
          return false;
        }

      break;
    }
    $modal = $('<div />');
    $modal.addClass('modal fade modal-sm')
        .attr('tabindex','-1')
        .attr('role','dialog')
        .attr('aria-labelledby','tituloAlerta')
        .attr('aria-hidden','true')
        .html(
          $('<div />')
            .addClass('modal-dialog modal-sm')
            .html(
              $('<div />')
                .addClass('modal-content')
                .html( tituloAlerta )
                .append(
                  $('<div />').addClass('modal-body alert-info')
                        .html( '<button type="button" class="close" data-dismiss="modal" aria-hidden="true">&times;</button>' )
                        .append( mensaje )
                        // .html( '<div class="alert alert-warning fade in">'+mensaje+'</div>' )
                )
            )
        );
    $('body').append( $modal );
    $modal.modal();
    $modal.on('hidden.bs.modal', function (e) {
      $(this).remove();
    })
}
  
  
