/*
 * busca y reemplaza el texto 'busca' dentro de 'text' con 'reemplaza'
 */
replaceAll = function ( text, busca, reemplaza ){
  while( text.toString().indexOf(busca) != -1 )
      text = text.toString().replace(busca,reemplaza);
  return text;
}

validarRequeridos = function (selector){
  console.log('ejecutando validacion');
  var datosValidos = true;
  $(selector).each(function(){
    if($(this).is("[required]")){
      var elementoValido = this.checkValidity();//verifica la validacion de HTML5
      if( $(this).is("[data-required]") ){//pregunta si trae el atributo data-required para aplicar validacion especial
        var validandoData = ejecutaValidacionRequeridos( $(this) );//envia el valor del atributo a procesar y validar
        elementoValido = elementoValido && validandoData;
      }
      if(!elementoValido){//si el elemento no es valido
        if( $(this).parent().is(".form-group") ){
          $(this).parent().addClass("has-error has-feedback");
          $(this).focusout(function(){
            $(this).parent().removeClass("has-error has-feedback");  
          });
        }else if( $(this).is(':radio') && $(this).parent().parent().is(".from-group") )
          $(this).parent().parent().addClass("has-error");
        else if( $(this).parent().is('div') && $(this).parent().parent().is(".form-group") ){
          $(this).parent().parent().addClass("has-error has-feedback");
          $(this).focusout(function(){
            $(this).parent().parent().removeClass("has-error has-feedback");  
          });
        }else if( $(this).is('select') ){
          $(this).parent().find('.btn').addClass('selectpicker-error');
        }else
          $(this).addClass("error-save");
      }else{/*mejorar esta validacion*/
        var validaAjax = $(this).prop("validaajax");//buscar el atributo validaajax
        if (typeof validaAjax !== "undefined"){//si lo encuentra ejecuta la validacion ajax
          elementoValido = elementoValido && $(this).inputValidacionAjax("esValido");
        }
      }
      datosValidos = datosValidos && elementoValido;
    }
    console.log('valido:' + datosValidos);
  });
  if( !datosValidos ){
    notify("Atención \n Hay información que es obligatoria para continuar", "error" );
    hideLoading();
  }
  
  return datosValidos;//regresa tru si paso todas las validaciones, false en caso contrario
}

