    $.widget("wr.input", {
        options: {
            className: 'wr-input',
            value: '',
            attr: {},
            blur: function () { },
            focus: function () { },
            keydown: function () { },
            keyup: function () { },
            disabled: false,
            width: '100%',
            formato: "texto"
        },
        _create: function () {
            var self = this,
                o = self.options,
                el = self.element;
            var $input = $("<input>")
                .val(o.value)
                .addClass('wr-input form-control')
                .addClass(o.className)
                .addClass(o.formato)
                .width(o.width);
            switch (o.formato) {
                case 'fecha':
                    break;
                case 'moneda':
                case 'real':
                case 'entero':
                    $input.bind({
                        keyup: function (event) {
                            var val = $(this).val();
                            if (isNaN(val)) {
                                val = val.replace(/[^0-9\.]/g, '');
                                if (val.split('.').length > 2)
                                    val = val.replace(/\.+$/, "");
                            }
                            if (val == null || val == "") { val = 0; }
                            $(this).val(val);
                        },
                        blur: function (event) {
                            o.blur(event);
                            var charFormat = ($(this).is('.moneda')) ? '$ ' : '';
                            var num = Math.round($(this).val() * 100) / 100;//para redondear a dos decimales
                            num = formatNumber(num, charFormat);
                            //si num es entero le quitamos los decimales con substring despues de darle formato, esto por que formatNumber siempre pone dos decimales
                            if ($(this).is('.entero')) { num = num.substring(0, (num.length - 3)); }
                            $(this).val(num);
                        },
                        focus: function (event) {
                            var num = unformatNumber($(this).val());
                            $(this).val(num);
                            o.focus(event);
                            // Marcos: Para intentar que se seleccione todo el texto al entrar al campo con el ratón
                            this.select();
                        },
                        keydown: function (event) {
                            var tp = true;//Tecla Permitida                                    punto 190, punto en bloq num 110 
                            //console.log(event.which);
                            if (($(this).is('.real') || $(this).is('.moneda')) && (event.which == 190 || event.which == 110))
                                tp = $(this).val().indexOf(".") >= 0; // Buscamos el punto para permitir solo 1 punto (indexOf = -1 si no lo encuentra)
                            if (event.shiftKey) {
                                tp = tp && event.which != 39 //left arrow
                                    && event.which != 46 //left arrow
                                    && event.which != 9 //tab
                                    && (event.which < 35 || event.which > 37);
                                // Marcos: para permitir CTRL-C y CTRL-V
                            } else if (event.ctrlKey) {
                                tp = tp && event.which != 67  // CTRL-C
                                    && event.which != 86; // CTRL-V
                            } else {
                                tp = tp && event.which != 8 //retroceso
                                    && event.which != 9 //tab
                                    && event.which != 13 //enter
                                    && event.which != 46 //supr
                                    && event.which != 109 //signo menos (-) bloqnum
                                    && (event.which < 35 || event.which > 40);//flechas
                            }
                            // teclas de          num alfanumerico             y                bloq num
                            if (event.which == 109)
                                $(this).val('');
                            if (!(event.which >= 48 && event.which <= 57) && !(event.which >= 96 && event.which <= 105) && tp) {
                                event.preventDefault();
                            } else o.keydown(event);
                        }
                    });
                    /*para aplicar el formato y demas, al inicializar un input*/
                    $input.blur();
                    break;
                default:
                    $input.bind({
                        blur: function (event) { o.blur(event); },
                        focus: function (event) { o.focus(event); },
                        keydown: function (event) { o.keydown(event); },
                        keyup: function (event) { o.keydown(event); }
                    });
                    // $input.bind({
                    // focus : function(){  self._trigger( 'focus' ); },
                    // blur  : function(){  self._trigger( 'blur' );  },
                    // keydown:function(event){ self._trigger( 'keydown' )}
                    // });
                    break;

            }

            $input.prop("disabled", o.disabled);
            for (var attrNombre in o.attr) {
                $input.attr(attrNombre, o.attr[attrNombre]);
            }

            el.append($input);
            if (o.formato == 'fecha')
                $input.datepicker({
                    showOn: "button",
                    buttonImage: "img/calendario.png",
                    buttonImageOnly: true,
                    changeMonth: true,
                    changeYear: true,
                    dateFormat: "dd/mm/yy",
                    showAnim: "slide"
                });
        },
        _setOption: function (key, value) {
            switch (key) {
                case 'value':
                    this.options.value = value;
                    this.element.children('input').val(value);
                    break;
                case 'blur':
                    this.options.blur = value;
                    break;
                case 'focus':
                    this.options.focus = value;
                    break;
                case 'keydown':
                    this.options.keydown = value;
                    break;
                case 'keyup':
                    this.options.keyup = value;
                    break;
            }
            this._super("_setOption", key, value);
        }
    });
