var ws_con = ((cxn, host) => {
    var connection;
    var ok = false;
    if (host !== undefined) {
        try {
            connection = new WebSocket('ws://' + host + ':8088');
        } catch (e) {
            console.log(e);
        }
    } else {
        connection = new WebSocket('ws://172.17.94.96:8088');
    }
    connection.onopen = (data => {
        connection.send(JSON.stringify({ "usr_id": cxn }));
        this.ok = true;
    });

    connection.open = () => {
        return this.ok;
    };

    connection.onerror = (error => {
        console.log(error);
    });
    connection.onmessage = (e => {
        console.log(e);
        var res = false;
        try {
            var res = JSON.parse(e.data);
        } catch (e) {
            this.send("error " + e);
        }
        if (res) {
            procesa(res);
        }
    });
    connection.sync = (d => {
        comunica("srv/Controlador.php", { metodo: "syncWebSocket" });
    });
    return connection;
});
procesa = function(d) {
    if (d === undefined) {
        return false;
    } else {
        if (d.type !== undefined) {
            switch (d.type) {
                case "notifica":
                    notifica(d.mensaje);
                    break;
            }
        }
    }
}

recargaCombo = function(id, data, detonar = false) {
    if ($("#" + id).length) {
        $("#" + id).empty();
        data.map(function (el, index) {
            let option = $('<option/>').prop('value', el.val).html(el.texto);
            if (el.selected) {
                option.attr('selected', 1);
            }
            Object.keys(el).map(function (index) {
                if (index != 'val' && index != 'texto') {
                    $(option).attr(index, el[index]);
                }
            });
            $("#" + id).append(option);
        });
        if (detonar) {
            $("#" + id).selectpicker('refresh').change();
        } else {
            $("#" + id).selectpicker('refresh');
        }
    }
}