formatNumber = function(num, prefix,dec){
  prefix = prefix || '';
  dec = dec || 2;
    num +='';
    var splitStr = num.split('.');
    var splitLeft = splitStr[0];
    
    if(splitStr[1])
      splitRight = splitStr[1];
  else
    splitRight  ="00";
            
//    var splitRight = splitStr.length > 1 ? '.' + splitStr[1] : '.00';
    var regx = /(\d+)(\d{3})/;
    while (regx.test(splitLeft)) {
      splitLeft = splitLeft.replace(regx, '$1' + ',' + '$2');
    }
  
  splitRight=splitRight.substring(0,dec);

  
  return prefix + splitLeft +"." + splitRight;
}



/**
* unformatNumber(num); quita el formato y prefijos a una cadena
* return devuelve el numero
*/
unformatNumber = function(num) {
    if (num && num.trim() !== '') {
        return num.replace(/([^0-9\.\-])/g,'')*1;
    }
    return 0;
}

$(function() {
  /* EVENTOS KEYPRESS PARA RESTRINGIR CARACTERES SEGUN SU CLASE 
  *  0: tab
  *  8 : retroceso, borrar
  *  32: espacio
  *  13: enter
  *  48-57: numeros
  *  44: coma
  *  45: menos
  *  46: punto
  *  95: guion bajo
  *  65-90: A-Z
  *  97-122:a-z
  *  
  */
  $(':text').on("keypress", function(event) {
    var anularTecla = false;
  // Busca si es uno de los caracteres permitidos en todos los inputs
    var esPermitido = Array.indexOf([0,8], event.which) >= 0;
    
    if( $(this).is(".entero") ) anularTecla = ((event.which < 48 ||  event.which > 57) && !esPermitido) ;
    
    if( $(this).is(".decimal") || $(this).is(".numero") || $(this).is(".moneda") ){
      // si la tecla pulsada en el punto (.) se busca si es que ya ingresaron un punto si es asi ya no se permite un segundo punto
      if(event.which == 46)  anularTecla = this.val().indexOf('.') >= 0;
      else anularTecla = ((event.which < 48 ||  event.which > 57) && !esPermitido) ;
    }
    if( anularTecla ) event.preventDefault();
    
  });  
});

/**
* pad(n, width, Z); rrellena con el caracter 'z', width posiciones a la izquierda
* return devuelve el numero formateado
*/
pad = function(n, width, z) {
  z = z || '0';
  n = n + '';
  return n.length >= width ? n : new Array(width - n.length + 1).join(z) + n;
}