myJq = {
    addJs:function(f)
    {
        var sc = document.getElementsByTagName("script");
        for (var x in sc)if (sc[x].src != null && sc[x].src.indexOf(f) != -1) return;include(f);
    },
    addCss:function(a)
    {
        $("head").append('<link href="'+a+'" rel="stylesheet" type="text/css" />');
    },
    addScript:function(a,id)
    {
        if ( $("contenedorScript").length < 1 ) {
            $("body").append( $("<contenedorScript/>"));
        }
        
        if ( ( id == "" ) || (typeof id === "undefined") ) {
            $("contenedorScript").append('<script type="text/javascript" language="javascript">try{'+a+'}catch( errorObject){console.info( errorObject );}</script>');
        } else {
            $("contenedorScript").append('<script type="text/javascript" id="' + id + '" language="javascript">try{'+a+'}catch( errorObject){console.info( errorObject );}</script>');
        }
    },
    addTemplate:function(a)
    {
        $("head").append('<script type="text/x-jquery-tmpl">'+a+'</script>');
    },
    addTemplate2:function(a,id)
    {
        $("#tmpls").append('<script id="'+id+'" type="text/x-jquery-tmpl">'+a+'</script>');
    },
    addStyle:function(a)
    {
        $("head").append("<style>"+a+"</style>");
    },
    addHtml:function(a,b,c)
    {
        if(c){
            $(a).html(b);
        } else {
            if(a){
                $("#"+a).html(b);
            } else {
                if ($("div#contenedor").length) $("div#contenedor").empty().slideUp(0).delay(100).html(b).fadeIn(800);
            };
        }
    }
};

