comunicaCallback = function (a)
{
    if(a.style){myJq.addStyle(a.style);}
    if(a.css){myJq.addCss(a.css);}
    if(a.html){
        for ( var contenedor in a.html ){
              cont = a.html[contenedor].tipo + contenedor;
              myJq.addHtml(cont,a.html[contenedor].codigo, 1);
        }
    }
    if(a.js){myJq.addJs(a.js);}
    if(a.script){myJq.addScript(a.script, a.idScript);}
    if(a.template){myJq.addTemplate(a.template);}
};
