file_exists = function(url)
{
    var req = this.window.ActiveXObject ? new ActiveXObject("Microsoft.XMLHTTP") : new XMLHttpRequest();
    if (!req) {
        throw new Error('XMLHttpRequest not supported');
    }
    req.open('head', url, false);
    req.send(null);
    if (req.status == 200) {
        return true;
    }
    return false;
};
