notify = function(d,e,f)
{
    /*------------------------------------------------------------------------------------------------------------
    Función genérica para mostrar avisos en la parte superior de la pantalla, es el equivalente a la función alerta(), 
    pero se quita después de un tiempo (configurable, igual que los colores)

    Colores: 
        success (verde, es del default), 
        warning (amarillo),
        information (gris)
        error (rojo)
    Uso: 
        notify( "esta es una notificación");
        notify( "Los datos son incorrectos", "error" );
    ------------------------------------------------------------------------------------------------------------*/
    d=typeof d!=="undefined"?d:"Notificacion";
    e=typeof e!=="undefined"?e:"success";
    if (e ==='error') {
        e = 'error-notification';
    }
    autoClose = true;
    switch(typeof f){ case 'boolean': autoClose = f; case 'undefined': f = 3000; break; };
    id = $(".notificationClass").length;
    $("body").append("<div id=\"notification" + 
        id +"\" class=\"information\"><span>Notificacion</span><a class=\"close\" href=\"#\"><i style='padding-top: 2px;' class='fa fa-times'></i></a></div>");
    $notification=$("#notification"+id);
    $notificationSpan=$("#notification"+id+" span");$notificationClose=$("#notification"+id+" a.close");
    $notificationSpan.text(d);
    $notificationClose.click(function(a){
        a.preventDefault(); 
        $(this).parent().animate({top:"-50px"},300,function() { $("#notification"+id).remove(); }); 
    });
    $notification.css("top","-50px").stop().removeClass().addClass(e+" notificationClass");
    $notification.animate({top:0},500,function(){ if(autoClose){
    $("#notification"+id).delay(f).animate({top:"-50px"},500,function() { $("#notification"+id).remove(); }); } });      
};
