convertArrayOfObjectsToCSV = function(args)
{
    // Marcos: 15/mayo/2017
    // Convertimos un objeto javascript en CSV
    // Se ocupó para la carga masiva, ya que crea un objeto con la lista de errores, y los muestre en el grid
    // y como había la necesidad de exportar ese objeto a CSV, encontramos éstas funciones
    var result, ctr, keys, columnDelimiter, lineDelimiter, data;

    data = args.data || null;
    if (data == null || !data.length) {
        return null;
    }

    columnDelimiter = args.columnDelimiter || ",";
    lineDelimiter = args.lineDelimiter || "\n";

    keys = Object.keys(data[0]);

    result = "";
    result += keys.join(columnDelimiter);
    result += lineDelimiter;

    data.forEach(function(item) {
        ctr = 0;
        keys.forEach(function(key) {
            if (ctr > 0) result += columnDelimiter;

            result += item[key];
            ctr++;
        });
        result += lineDelimiter;
    });

    return result;
}
downloadCSV = function(args)
{
    /* Esta es la función que se llama, y que debe contener como mínimo el objeto a exportar
    Ejemplo de uso: downloadCSV({ objetoAExportar: dataCarga, filename: "cargaMasivaPolizas.xls" }); 
    */
    var data, filename, link;
    var csv = convertArrayOfObjectsToCSV({
        data: args.objetoAExportar
    });
    var BOM = "\uFEFF";   // Le ponemos el BOM al inicio, para que cuando excel lo abra respete el UTF-8
    if (csv == null) return;

    filename = args.filename || "export.csv";

    if (!csv.match(/^data:text\/csv/i)) {
        csv = "data:text/csv;charset=utf-8," + BOM + csv;
    }
    data = encodeURI(csv);

    link = document.createElement("a");
    link.setAttribute("href", data);
    link.setAttribute("download", filename);
    link.click();
}
window.comunicaApi = async function (ruta, parametros) {
    var formData = new FormData();
    Object.keys(parametros).map(el => {
        formData.append(el, parametros[el]);
    })
    var res;
    var req = await axios({
        method: "POST",
        url: ruta,
        data: formData,
        dataType: atob("anNvbg=="),
        async: false,
        headers: {
            'Content-Type': 'multipart/form-data'
        }
    });
    return req.data;
}
window.comunicaBlank = function (ruta, prm) {
    var sfpreq = document.createElement('FORM');
    sfpreq.method = 'POST';
    sfpreq.action = ruta;
    sfpreq.target = "_blank";

    Object.keys(prm).map((el) => {
        var my_tb = document.createElement('INPUT');
        my_tb.name = el;
        my_tb.type = atob("aGlkZGVu");
        my_tb.value = prm[el];
        sfpreq.appendChild(my_tb);
    });
    document.body.appendChild(sfpreq);
    sfpreq.submit();
    sfpreq.remove();
}