load_destino = function (id, t) {
  var div = null;
  if (t !== undefined && (t.toLowerCase() == "d" || t.toLowerCase() == "div")) {
    div = $("<div/>")
      .css("background-color", "#FFF")
      .css("height", "95%")
      .css("padding", "10px")
      .css("overflow", "hidden")
      .css("overflow", "scroll")
      .attr("id", "det_fs" + id);
  } else {
    div = $("<iframe/>")
      .attr("id", "det_fs" + id)
      .attr("name", "det_fs" + id)
      .css("width", "100%")
      .css("height", "98%")
      .css("background-image", "url(data:image/gif;base64,)")
      .css("background-repeat", "no-repeat")
      .css("background-position", "50% 30%");
  }
  return div;
}

load_viewer = function (id, titulo, t, contenedor, zindex) {
  if (zindex == undefined) {
    zindex = 10000;
  }

  if (contenedor == undefined)
    contenedor = "";

  if (!($("#fs" + id).length != 1)) {
    $("#fs" + id).attr("edo", "m").animate({ opacity: 1, top: "0px", left: "0px", width: "100%", height: "100%" }, 500);
    return false;
  }

  if ($("#sty_viewer").length != 1)
    load_css();

  var dest = load_destino(id, t);
  var tit = titulo !== undefined ? titulo : "...";
  this.title = $("<div>").css("width", "100%").css("display", "inline-block").html(tit).attr("id", id + "toolsviewer");
  this.setTitle = function (titulo) {
    if (titulo != undefined && titulo != "")
      this.title.html(titulo);
  }


  tools_bar = $("<div/>").addClass("tool_bar_vista")
    .prop("id", "dragable_" + id)
    .on('dblclick', function () {
      var w = $("#fs" + id).attr("edo");
      if (w == "m") $("#fs" + id).attr("edo", "n").animate({ top: "20px", left: "10%", width: "80%", height: "90%" }, 500);
      else $("#fs" + id).attr("edo", "m").animate({ top: "0px", left: "0px", width: "100%", height: "100%" }, 500);
    })
    .append(this.title);
  tools = $("<div/>").css("position", "absolute").css("top", "6px").css("right", "10px");
  m = $("<a/>").append(
    $("<img/>").attr("src", "data:image/png;base64,")
  ).on('click', function () {
    $("#fs" + id).animate({ "height": "38px", width: "550px", left: "10px", top: "80%" }, 400);
  }
  ).appendTo(tools);
  x = $("<a/>").append(
    $("<img/>").attr("src", "data:image/png;base64,")
  ).on('click', function () {
    var w = $("#fs" + id).attr("edo");
    if (w == "m") $("#fs" + id).attr("edo", "n").animate({ top: "20px", left: "10%", width: "80%", height: "90%" }, 500);
    else $("#fs" + id).attr("edo", "m").animate({ top: "0px", left: "0px", width: "100%", height: "100%" }, 500);
  })
    .appendTo(tools);
  x = $("<a/>").append(
    $("<img/>").attr("src", "data:image/png;base64,")
  ).attr("id", id + "close_jma_viewer")
    .on('click', function () { $("#fs" + id).animate({ opacity: 0, height: "0px", width: "0px" }, 400, function () { $("#fs" + id).remove(); }); })
    .appendTo(tools);
  tools_bar.append(tools);
  this.viewer = $("<div/>").addClass("documento_fs")
    .attr("edo", "n")
    .attr("id", "fs" + id)
    .draggable({ handle: "#dragable_" + id, containment: contenedor })
    .append(tools_bar)
    .append($("<div/>").attr("id", "viewer_extra"))
    .append(dest)
    .css("z-index", zindex)
    .css("position", "fixed")
    ;
  this.max = function () {
    this.viewer.css("height", "auto");
  }

  this.viewer.appendTo($("body"));

  return true;
}

load_css = function () {
  if ($("#sty_viewer").length != 1) {
    sty = $("<style/>")
      .attr("type", "text/css")
      .attr("id", "sty_viewer")
      .html(".tool_bar_vista{transition: background ease-in-out .3s;height:50px;border:1px solid #333; padding:10px; font-size:16px; color:#FFF;color: rgb(0, 0, 0);margin-left: -16px; margin-right: -16px;margin-top: -16px;border-top: 1px solid #333;background-color:#fff;color:#000;}.tool_bar_vista:hover{background-color:#EAEAEA;}")
      .appendTo(document.head);
  }
}
